class TaskBinding{static Object truck(int p,int f,int m,int c){return new Truck(p,f,m,c);}static int cargo(Object x){return ((Truck)x).getCargo();}static void cargo(Object x,int c){((Truck)x).putCargo(c);}static int[]state(Object x){Vehicle v=(Vehicle)x;return new int[]{v.getPassengers(),v.getFuelcap(),v.getMpg()};}static int range(Object x){return ((Vehicle)x).range();}static double fuel(Object x,int miles){return ((Vehicle)x).fuelNeeded(miles);}static void setFuel(Object x,int f){((Vehicle)x).setFuelcap(f);}}
